  const details=el('details');details.append(el('summary','Task breakdown and exact cases'));
  const table=el('table'),head=el('tr');for(const t of ['Recorded task','Earlier','Recent','Included','Cases'])head.append(el('th',t));table.append(head);
  for(const task of m.tasks){const row=el('tr'),cell=el('td'),button=el('button','Inspect task');
    button.onclick=()=>{const ids=new Set([...task.focus.ids,...task.reference.ids]),cases=v.cases.filter(c=>ids.has(JSON.stringify([c.producer,c.chain_id])));inspect('Task comparison · '+task.task_id,chainRows(cases),{schema:m.schema,metric:comparisonMetric,protocol:v.protocol,outcome:v.outcome,coordinates:window.coordinates,task,cases,definition:m.definition});};
    cell.append(button);row.append(el('td',task.task_id),el('td',`${pct(task.reference)} · ${count(task.reference)} decided · ${task.reference.unknown} unresolved`),el('td',`${pct(task.focus)} · ${count(task.focus)} decided · ${task.focus.unknown} unresolved`),el('td',task.shared?'Both windows':'One window only'),cell);table.append(row);}
  details.append(tableWrap(table));panel.append(details);
