  const contextTable=el('table'),contextHead=el('tr');for(const t of ['Window','Retry input','Environment reset','Chains'])contextHead.append(el('th',t));contextTable.append(contextHead);
  for(const side of ['reference','focus'])for(const x of window.retry_context[side]){const row=el('tr');row.append(el('td',side==='focus'?'Recent':'Earlier'),el('td',human(x.context)),el('td',human(x.reset)),el('td',String(x.chains)));contextTable.append(row);}
  contexts.append(tableWrap(contextTable),el('p','Recorded initial failures with retry budget only. Missing retries remain visible; a context declaration does not prove the model used that feedback.','th-coverage'));panel.append(contexts);
