   for(const p of timeline.points){const row=el('tr'),cell=el('td'),button=el('button','Inspect');button.onclick=()=>inspectBehaviorPoint(title+' · '+axis+' '+p.step,p,timeline,context);cell.append(button);row.append(el('td',fmt(p.step)),el('td',format(p)),el('td',`${p.source_measured} / ${p.source_rollouts}`),el('td',fmt(p.unbound_samples)),cell);table.append(row);}
   details.append(tableWrap(table));
   if(timeline.unplaced.declared_samples){const button=el('button',`${timeline.unplaced.declared_samples} samples without a progress coordinate`);button.onclick=()=>inspectBehaviorPoint('Unplaced generation samples',timeline.unplaced,timeline,context);details.append(button);}
